class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        a = [(nums[i + 1] > nums[i]) - (nums[i + 1] < nums[i]) for i in range(n - 1)]
        m = len(pattern)
        ans = 0
        for i in range(len(a) - m + 1):
            if all(a[i + k] == pattern[k] for k in range(m)):
                ans += 1
        return ans

