class Solution {
public:
    int countMatchingSubarrays(vector<int>& nums, vector<int>& pattern) {
        int n = nums.size(), m = pattern.size();
        vector<int> a(n - 1);
        for (int i = 0; i + 1 < n; i++)
            a[i] = (nums[i + 1] > nums[i]) - (nums[i + 1] < nums[i]);
        int ans = 0;
        for (int i = 0; i + m <= (int)a.size(); i++) {
            bool ok = true;
            for (int k = 0; k < m && ok; k++) if (a[i + k] != pattern[k]) ok = false;
            ans += ok;
        }
        return ans;
    }
};

