var countMatchingSubarrays = function(nums, pattern) {
    const a = [];
    for (let i = 0; i + 1 < nums.length; i++)
        a.push(Math.sign(nums[i + 1] - nums[i]));
    const m = pattern.length, lps = Array(m).fill(0);
    for (let i = 1, k = 0; i < m; i++) {
        while (k && pattern[i] !== pattern[k]) k = lps[k - 1];
        if (pattern[i] === pattern[k]) k++;
        lps[i] = k;
    }
    let ans = 0, k = 0;
    for (const x of a) {
        while (k && x !== pattern[k]) k = lps[k - 1];
        if (x === pattern[k]) k++;
        if (k === m) { ans++; k = lps[k - 1]; }
    }
    return ans;
};
